// Generated files are left out of a review: out of the line count, the risk and the diff the reviewer reads (a 21k-line golden JSON made a
// normal change look high risk). A file is generated when .gitattributes marks it linguist-generated, when it is a snapshot (`*.snap`), lives
// under golden / fixtures / __snapshots__, is a lockfile or a minified bundle, or matches a `review.exclude` glob of config.json. Pure
// helpers plus one git call (check-attr); a git that does not answer leaves the attribute rule out and says so.
import type { Host } from './state'

const LOCKFILES = new Set(['package-lock.json', 'pnpm-lock.yaml', 'yarn.lock', 'Cargo.lock', 'go.sum', 'poetry.lock'])
const GENERATED_DIR = /(^|\/)(golden|goldens|fixtures?|__snapshots__)(\/|$)/i
const base = (p: string) => p.slice(p.lastIndexOf('/') + 1)

// the built-in rules, by path alone
export const builtinGenerated = (path: string): boolean =>
  LOCKFILES.has(base(path)) || /\.snap$/.test(path) || GENERATED_DIR.test(path) || /\.min\.(?:js|mjs|cjs|css)$/i.test(base(path))

// gitignore-like globs: `**` any depth, `*` and `?` inside one name; a glob with no `/` matches a name at any depth, one with a `/` the
// whole path (a leading `/` anchors it at the root); a trailing `/` is a folder and everything under it
export function globRe(g: string): RegExp {
  let p = g.trim()
  const anyDepth = !p.includes('/') || (p.indexOf('/') === p.length - 1 && p.endsWith('/'))
  if (p.startsWith('/')) p = p.slice(1)
  const dir = p.endsWith('/')
  if (dir) p = p.slice(0, -1)
  const body = p.replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*\*\/?/g, m => (m.endsWith('/') ? '\u0001' : '\u0002')).replace(/\*/g, '[^/]*').replace(/\?/g, '[^/]').replace(/\u0001/g, '(?:.*/)?').replace(/\u0002/g, '.*')
  return new RegExp(`^${anyDepth && !g.trim().startsWith('/') ? '(?:.*/)?' : ''}${body}${dir ? '(?:/.*)?' : ''}$`)
}
export const globsOk = (v: unknown): string[] => (Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string' && !!x.trim()).slice(0, 100) : [])

// which of `names` the .gitattributes mark linguist-generated (set or true); the answer of `git check-attr`, in chunks
async function attributed(h: Host, repo: string, names: string[]): Promise<{ hit: Set<string>; failed: boolean }> {
  const hit = new Set<string>()
  for (let i = 0; i < names.length; i += 150) {
    const r = await h.process.run(['git', '-C', repo, 'check-attr', 'linguist-generated', '--', ...names.slice(i, i + 150)], { timeoutMs: 30_000 }).catch(() => null)
    if (!r || r.exitCode !== 0) return { hit, failed: true }
    for (const l of r.stdout.split('\n')) {
      const m = /^(.*): linguist-generated: (\S+)$/.exec(l)
      if (m && (m[2] === 'set' || m[2] === 'true')) hit.add(m[1]!)
    }
  }
  return { hit, failed: false }
}

export type Excluded = { files: string[]; lines: number; attrFailed?: boolean; attrSkipped?: boolean } // files: the biggest first
// the files of `names` a review leaves out, with the reason of each
// The change under review must not mark its own files generated: when a .gitattributes is among the changed files the attribute rule is not
// applied at all (attrSkipped), whatever it says; the by-name rules and the user's own config globs still are.
export async function generatedFiles(h: Host, repo: string, names: string[], globs: string[]): Promise<{ files: Map<string, string>; attrFailed: boolean; attrSkipped: boolean }> {
  const attrSkipped = names.some(n => base(n) === '.gitattributes')
  const files = new Map<string, string>()
  const res = globs.map(g => [g, globRe(g)] as const)
  const left: string[] = []
  for (const n of names) {
    if (builtinGenerated(n)) files.set(n, 'generated by name (snapshot, golden, fixture, lockfile or minified)')
    else {
      const g = res.find(([, re]) => re.test(n))
      if (g) files.set(n, `config review.exclude ${g[0]}`)
      else left.push(n)
    }
  }
  const a = left.length && !attrSkipped ? await attributed(h, repo, left) : { hit: new Set<string>(), failed: false }
  for (const n of a.hit) files.set(n, '.gitattributes linguist-generated')
  return { files, attrFailed: a.failed, attrSkipped }
}

// the diff text without the sections of `drop`, and how many added/removed lines were dropped (in all, and per file)
export function dropSections(diff: string, drop: Set<string>): { diff: string; lines: number; per: Map<string, number> } {
  const per = new Map<string, number>()
  if (!drop.size) return { diff, lines: 0, per }
  const out: string[] = []
  let lines = 0
  let skipping: string | null = null
  for (const line of diff.split('\n')) {
    if (line.startsWith('diff --git ')) {
      const m = /^diff --git a\/(.*) b\/(.*)$/.exec(line)
      skipping = m ? (drop.has(m[2]!) ? m[2]! : drop.has(m[1]!) ? m[1]! : null) : null
    }
    if (skipping === null) out.push(line)
    else if (/^[+-]/.test(line) && !/^(\+\+\+|---)/.test(line)) { lines++; per.set(skipping, (per.get(skipping) ?? 0) + 1) }
  }
  return { diff: out.join('\n'), lines, per }
}

// what the prepare text says, and the pathspecs that keep those files out of the diff the reviewer reads (the biggest ones first)
export const EXCLUDE_SPECS = 40
export function excludeSpecs(ex: Excluded | undefined): string {
  if (!ex?.files.length) return ''
  // :(exclude,literal): a `*`, `?` or `[` in a file name is that character, not a glob that could hide more than the file
  return ex.files.filter(f => !/['\n\r]/.test(f)).slice(0, EXCLUDE_SPECS).map(f => `':(exclude,literal)${f}'`).join(' ') // (a name with a quote could not be written as one plain word)
}
export function excludedText(ex: Excluded | undefined): string {
  if (!ex?.files.length) return ''
  const shown = ex.files.slice(0, 15).join(', ')
  const notes = [ex.attrFailed ? 'git check-attr did not answer, so .gitattributes marks were not applied' : '', ex.attrSkipped ? 'a .gitattributes is among the changed files, so its marks were not applied (the change must not mark its own files generated)' : ''].filter(Boolean)
  return `Generated files left out of the lists, the risk and the line count: ${ex.files.length} file${ex.files.length === 1 ? '' : 's'}, ${ex.lines} line${ex.lines === 1 ? '' : 's'} (${shown}${ex.files.length > 15 ? ', ...' : ''}). Do not review them; if one of them is hand-written code (named like a fixture or snapshot but holding logic), say so in "missing"${notes.length ? ` (${notes.join('; ')})` : ''}.`
}
